<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ArrowRight} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createRun} from '../api/runs';import {getVersions} from '../api/phases';import {PhaseVersion} from '../types/domain';import StudySelector from '../components/StudySelector.vue';import Notice from '../components/common/Notice.vue';import {VersionStatus} from '../constants/enums';const s=useResearchData(),auth=useAuth(),a=useAction(),router=useRouter(),route=useRoute(),id=ref(Number(route.query.study)||0),name=ref(''),delta=ref(.001),B=ref(199),seed=ref(2026),versions=ref<PhaseVersion[]>([]),versionId=ref<number|null>(null);const study=computed(()=>s.studies.find(x=>x.id===id.value)||s.studies[0]);const picked=computed(()=>versions.value.find(v=>v.id===versionId.value)||versions.value.find(v=>v.status==='active')||versions.value[0]);const analyzable=computed(()=>versions.value.filter(v=>v.status!=='invalidated'));watch(()=>route.query.study,value=>{if(value)id.value=Number(value)});async function loadVersions(){if(!study.value)return;try{versions.value=await getVersions(study.value.id);versionId.value=(versions.value.find(v=>v.status==='active')||versions.value[0])?.id??null}catch{versions.value=[]}}watch(()=>study.value?.id,loadVersions,{immediate:true});function submit(){a.execute(async()=>{const r=await createRun({name:name.value,study_id:study.value.id,phase_version_id:picked.value?.id,delta:delta.value,permutations:B.value,seed:seed.value});router.push('/results?run='+r.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">REPLACEMENT & PERMUTATION / 04</p><h1>替换与置换配置<span>δ是比例假设，组规模在置换中保持。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><div class="editor-grid"><form @submit.prevent="submit"><label>研究名称<input aria-label="研究名称" v-model="name" minlength="2" maxlength="160" required placeholder="例如：零分量三工艺组成复核" :disabled="auth.user?.role==='viewer'"/></label><StudySelector :studies="s.studies" :model-value="study?.id||0" @update:model-value="id=$event"/><label>相通道版本<select aria-label="相通道版本" v-model.number="versionId"><option v-for="v in analyzable" :key="v.id" :value="v.id">v{{v.version}} / {{v.label}} · {{VersionStatus[v.status]}} · {{v.component_count}}通道</option></select></label><p class="caption">默认使用当前生效版本。已退役版本仍可分析，用于复核历史结果的旧相依据；已失效的竞争版本不可选用。运行创建时冻结所选版本的通道与样本快照。</p><div v-if="study" :class="['source-note',!study.supported?'warning':'']"><b>{{study.reason}}</b><p>{{study.sample_count}}样本 / {{study.zero_rows}}行含零 / {{Object.entries(study.group_counts).map(([g,n])=>g+' '+n).join(' / ')}}</p></div><div class="form-heading"><span>01</span><h2>显式乘法零替换</h2></div><label>delta / 闭合后比例<input aria-label="零替换delta" type="number" min="0.0001" max="0.9999" step="0.0001" v-model.number="delta"/></label><p class="protocol">z个零各置δ，原正份额乘(1−zδ)，每行要求0&lt;δ&lt;1/z。没有零的行只闭合，不加伪计数。所有替换前后与CLR坐标保留。</p><div class="form-heading"><span>02</span><h2>全局标签置换</h2></div><div class="form-row"><label>置换次数<input aria-label="置换次数" type="number" min="199" max="999" v-model.number="B"/></label><label>根随机种子<input aria-label="随机种子" type="number" min="0" max="2147483647" v-model.number="seed"/></label></div><p class="caption">固定各组规模，R²上尾+1，保存全部{{B}}个null R²。最小p分辨率{{(1/(B+1)).toFixed(4)}}。样本数×置换数≤150000。</p><button v-if="auth.user?.role!=='viewer'" class="primary" :disabled="a.busy.value||!picked" @click.prevent="submit">提交组成研究 <ArrowRight :size="15"/></button><p v-else class="role-note">阅读者可核对配置，提交需要研究员权限。</p></form><aside class="method-note"><span class="eyebrow">GEOMETRY NOTE / 29</span><h2>闭合之前，<br/>先写清楚假设。</h2><ol><li><b>CLR几何</b><p>log份额减行内log均值，距离为CLR欧氏距离。</p></li><li><b>R²与无界F</b><p>SST=0未定义；SSW=0时R²1、F无界，置换仍比较有限R²。</p></li><li><b>组差有多种解释</b><p>离散度也可影响PERMANOVA；这里只给组内距离描述，未检验同质性或工艺原因。</p></li></ol></aside></div></div></template>
